## 2. C++ (C++17)

```cpp
// fib_dp.cpp
// Compile with: g++ -std=c++17 -O2 -Wall fib_dp.cpp -o fib_dp
#include <iostream>
#include <stdexcept>

long long fib(int n) {
    if (n < 0) throw std::invalid_argument("n must be non‑negative");
    if (n == 0) return 0;
    if (n == 1) return 1;

    long long prev = 0, cur = 1;
    for (int i = 2; i <= n; ++i) {
        long long nxt = prev + cur;
        prev = cur;
        cur = nxt;
    }
    return cur;
}

int main() {
    int n;
    std::cout << "Enter n: ";
    if (!(std::cin >> n)) {
        std::cerr << "Invalid input.\n";
        return 1;
    }

    try {
        std::cout << fib(n) << '\n';
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return 1;
    }
    return 0;
}
```

