## Full Source Code (C++17)

```cpp
/*****************************************************************
 *  word_counter.cpp
 *
 *  Reads a text file line‑by‑line and counts how many times a
 *  specific word occurs in the file.
 *
 *  Usage:
 *      word_counter <file_path> <word> [options]
 *
 *  Options:
 *      -i            case‑insensitive matching (default: case‑sensitive)
 *
 *  Example:
 *      $ ./word_counter mybook.txt the
 *      The word "the" occurs 1234 times in "mybook.txt".
 *
 *  Compile (C++17):
 *      g++ -std=c++17 -O2 -Wall -Wextra -o word_counter word_counter.cpp
 *
 *****************************************************************/

#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <algorithm>   // std::transform, std::tolower
#include <cctype>      // std::tolower
#include <vector>

// Utility: trim whitespace from both ends of a string
static std::string trim(const std::string& s)
{
    const auto start = s.find_first_not_of(" \t\r\n");
    if (start == std::string::npos) return "";               // string is all whitespace
    const auto end = s.find_last_not_of(" \t\r\n");
    return s.substr(start, end - start + 1);
}

// Utility: convert a string to lower case (in‑place)
static void to_lower_inplace(std::string& s)
{
    std::transform(s.begin(), s.end(), s.begin(),
                   [](unsigned char ch){ return static_cast<char>(std::tolower(ch)); });
}

// Split a line into whitespace‑separated tokens (words)
static std::vector<std::string> split_into_words(const std::string& line)
{
    std::istringstream iss(line);
    std::vector<std::string> tokens;
    std::string token;
    while (iss >> token)              // operator>> skips any whitespace
        tokens.emplace_back(std::move(token));
    return tokens;
}

// ---------------------------------------------------------------
// Main program
// ---------------------------------------------------------------
int main(int argc, char* argv[])
{
    // -----------------------------------------------------------------
    // 1️⃣  Parse command‑line arguments
    // -----------------------------------------------------------------
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <file> <word> [-i]\n"
                  << "  <file>   path to a readable text file\n"
                  << "  <word>   word to search for\n"
                  << "  -i       case‑insensitive matching (optional)\n";
        return 1;
    }

    const std::string filePath = argv[1];
    const std::string targetWord = trim(argv[2]);   // remove stray spaces

    // optional flag for case‑insensitivity
    const bool caseInsensitive = (argc > 3 && std::string(argv[3]) == "-i");

    // Normalise target word according to the chosen matching mode
    const std::string targetForCompare = caseInsensitive ? targetWord : ""; // stay unchanged
    // If case‑insensitive we also keep a lowercase version for quick comparison
    std::string targetLower = caseInsensitive ? targetWord : "";
    if (caseInsensitive)
        to_lower_inplace(targetLower);

    // -----------------------------------------------------------------
    // 2️⃣  Open the file
    // -----------------------------------------------------------------
    std::ifstream infile(filePath, std::ios::in);
    if (!infile) {
        std::cerr << "Error: Cannot open file \"" << filePath << "\" for reading.\n";
        return 1;
    }

    // -----------------------------------------------------------------
    // 3️⃣  Process the file line‑by‑line
    // -----------------------------------------------------------------
    std::size_t totalOccurrences = 0;
    std::string line;
    std::size_t lineNumber = 0;

    while (std::getline(infile, line)) {
        ++lineNumber;

        // Split current line into tokens (words)
        const std::vector<std::string> words = split_into_words(line);

        for (const std::string& rawToken : words) {
            // Trim punctuation that might be attached to the word
            // (e.g., "hello," -> "hello")
            std::string token = rawToken;
            // Remove leading punctuation
            token.erase(token.begin(),
                        std::find_if(token.begin(), token.end(),
                                     [](unsigned char ch){ return std::isalnum(ch); }));
            // Remove trailing punctuation
            token.erase(std::find_if(token.rbegin(), token.rend(),
                                     [](unsigned char ch){ return std::isalnum(ch); }).base(),
                        token.end());

            if (token.empty()) continue; // skip tokens that became empty after trimming

            // Compare with target word
            bool match = false;
            if (caseInsensitive) {
                std::string lowered = token;
                to_lower_inplace(lowered);
                match = (lowered == targetLower);
            } else {
                match = (token == targetWord);
            }

            if (match) ++totalOccurrences;
        }
    }

    // -----------------------------------------------------------------
    // 4️⃣  Report result
    // -----------------------------------------------------------------
    std::cout << "The word \"" << targetWord << "\" occurs "
              << totalOccurrences << " time"
              << (totalOccurrences == 1 ? "" : "s")
              << " in \"" << filePath << "\".\n";

    return 0;
}
```

